    qc.mcp(angle=-1*3.141592653589793, control_qubits=range(n-1), target_qubit=n-1)
    qc.x(range(n))

    if L < 2**n:
        num_controls = 0
        temp = L
        while temp > 0:
            num_controls += 1
            temp >>= 1

        control_qubits = []
        for i in range(n):
            if i >= num_controls:
                qc.x(i)
            else:
                if ((L >> i) & 1) == 0:
                    qc.x(i)
                control_qubits.append(i)

        qc.mcp(angle=3.141592653589793, control_qubits=control_qubits, target_qubit=n-1)

        for i in range(n):
            if i >= num_controls:
                qc.x(i)
            else:
                if ((L >> i) & 1) == 0:
                    qc.x(i)

    return qc

