from qiskit.circuit.library import XGate

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    # Create a bitmask for L
    bitmask = bin(L - 1)[2:].zfill(n)

    # Apply X gates to the qubits where the bitmask has 0
    for i in range(n):
        if bitmask[n - 1 - i] == '0':
            qc.x(i)

    # Apply a multi-controlled Z gate
    if n > 1:
        qc.append(XGate().control(n - 1), range(n))
    else:
        qc.z(0)

    # Apply X gates to the qubits where the bitmask has 0 (to revert them)
    for i in range(n):
        if bitmask[n - 1 - i] == '0':
            qc.x(i)

    return qc

