def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if L == 1:
        return qc
    elif L == 2**n:
        for i in range(n):
            qc.h(i)
        return qc
    else:
        angle = 2 * np.arcsin(np.sqrt(1 / L))
        qc.ry(angle, 0)

        def apply_controlled_ry(qc, control_qubits, target_qubit, angle):
            num_control = len(control_qubits)
            if num_control == 0:
                qc.ry(angle, target_qubit)
            elif num_control == 1:
                qc.cry(angle, control_qubits[0], target_qubit)
            else:
                # Decompose multi-controlled RY gate
                theta = angle / 2**(num_control - 1)

                qc.cry(theta, control_qubits[num_control - 1], target_qubit)

                if num_control > 1:
                    apply_controlled_ry(qc, control_qubits[:num_control-1], target_qubit, theta)
                    qc.cx(control_qubits[num_control-1], control_qubits[num_control-2])
                    apply_controlled_ry(qc, control_qubits[:num_control-1], target_qubit, -theta)
                    qc.cx(control_qubits[num_control-1], control_qubits[num_control-2])
                    apply_controlled_ry(qc, control_qubits[:num_control-1], target_qubit, theta)


        for i in range(1,L):
            binary_representation = bin(i)[2:].zfill(n)
            control_qubits = []
            for j in range(n):
                if binary_representation[n-1-j] == '1':
                    control_qubits.append(j)
                else:
                    qc.x(j)
                    control_qubits.append(j)

            apply_controlled_ry(qc, control_qubits, 0, angle)

            for j in range(n):
                if binary_representation[n-1-j] == '0':
                    qc.x(j)
