def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x, y = QuantumRegister(n, 'x'), QuantumRegister(m, 'y')
    qc = QuantumCircuit(x, y)

    # Compute f(x) modulo 2^m and store in y
    for i in range(n):
        for j in range(m):
            if (S[i] >> j) & 1:
                qc.cx(x[i], y[j])

    # Compare f(x) with L
    # Create a temporary ancilla qubit
    anc = QuantumRegister(1, 'anc')
    qc.add_register(anc)
    qc.mcx(y, anc[0])

    l_binary = bin(L)[2:].zfill(m)
    for i in range(m):
