def solve(n: int, m: int, a: int, L: int) -> QuantumCircuit:
    x, y = QuantumRegister(n, name='x'), QuantumRegister(2 * m + 1, name='y')
    qc = QuantumCircuit(x, y)

    # Apply Hadamard gates to x register to create superposition
    for i in range(n):
        qc.h(x[i])

    # Define modular exponentiation function
    def modular_exponentiation(a, k, L, m):
        qc_mod_exp = QuantumCircuit(2 * m + 1)

        a_power = a
        for i in range(k):
            if (k >> i) & 1:
                qc_mod_exp.compose(modular_multiplication(a_power, L, m), inplace=True)
            a_power = (a_power * a_power) % L  # Calculate a^(2^i) mod L

        return qc_mod_exp

    # Define modular multiplication function
    def modular_multiplication(a, L, m):
        qc_mod_mult = QuantumCircuit(2 * m + 1)
        for i in range(L):
            if (L >> i) & 1:
                qc_mod_mult.cx(2 * m - i, 2 * m)

        # Classical addition of a to y modulo L
        for i in range(a):
            qc_mod_mult.x(2 * m)

        return qc_mod_mult

    # Apply controlled modular exponentiation
    for i in range(n):
        qc_temp = modular_exponentiation(a, 2**i, L, m)
        qc_controlled = qc_temp.control(num_ctrl_qubits=1)
        qc.append(qc_controlled, [x[i]] + list(y))

    return qc

