def solve(n: int, m_left: int, k_left: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    qc.barrier()
    if m_left == 1:
        qc.x(0)

    for i in range(n):
        if (k_left >> i) & 1:
            angle = 2 * (2 * i + 1) * 3.141592653589793 / (2 ** n)
            qc.p(angle, i + 1)

    qc.barrier()
    return qc

