def solve(n: int, m_left: int, k_left: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    # Apply X gate if m_left is 1
    if m_left == 1:
        qc.x(0)

    # Apply R^k_left gates
    for i in range(n):
        if (k_left >> i) & 1:
            angle = 2 * 3.141592653589793 / (2**(n - 1 - i))
            qc.rz(angle, 0)

    # CNOT gate controlled by the first qubit to the second qubit
    qc.cx(0, 1)

    # Apply R^{-k_left} gates if the control qubit (qubit 1) is 1 and m is 1
    if m_left == 1:
        for i in range(n):
            if (k_left >> i) & 1:
                angle = -2 * 3.141592653589793 / (2**(n - 1 - i))
                qc.rz(angle, 0)

    # Apply X gate if m_left is 1
    if m_left == 1:
        qc.x(0)


    return qc

