def solve(n: int, m_left: int, k_left: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    # Write your code here:
    qc.x(0)  # Apply X gate to qubit 0
    if m_left == 1:
        qc.cx(0, n)
    for i in range(n):
        if (k_left >> i) & 1:
            qc.p(2 * 3.141592653589793 / (2**(n - i - 1)), n)  # Apply R gate to qubit n
    if m_left == 1:
        qc.cx(0, n)
    qc.x(0)

    return qc

