def solve(n: int, m_before: int, k_before: int, m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)
    # Write your code here:

    k_total = (k_before + k_after) % (2**n)

    qc.x(range(1,n+1))

    def adder(qc, a, b, c, n):
        for i in range(n):
            qc.cx(a[i], c[i])
            qc.cx(b[i], c[i])
            qc.ccx(a[i], b[i], a[i+1])
        qc.cx(a[n], c[n])

    def inv_adder(qc, a, b, c, n):
        qc.cx(a[n], c[n])
        for i in range(n-1, -1, -1):
            qc.ccx(a[i], b[i], a[i+1])
            qc.cx(b[i], c[i])
            qc.cx(a[i], c[i])

    def constant_adder(qc, a, n, k):
      binary_k = bin(k)[2:].zfill(n)
      for i in range(n):
        if binary_k[n-1-i] == '1':
          qc.cx(a[i],0)

    a = list(range(1,n+1))
    constant_adder(qc, a, n, k_before)

    for i in range(n):
      qc.cx(i+1,0)

    constant_adder(qc, a, n, k_after)

    if m_before == 1:
        qc.x(0)

    if m_after == 1:
        qc.x(0)

    return qc

from qiskit import QuantumCircuit


def solve(n: int, m_before: int, k_before: int, m_after: int, k_after: int) -> QuantumCircuit:
    qc = QuantumCircuit(n + 1)

    # Calculate the new m and k values
    m_new = (m_before + m_after) % 2
    k_new = (k_before + k_after) % (2**n)

    # Apply m_before
    if m_before == 1:
        qc.x(0)

    # Apply k_before
    for i in range(n):
        if (k_before >> i) & 1:
            qc.cx(i + 1, 0)

    # Apply m
    qc.cx(0, 0)

    # Apply k
    for i in range(n):
        qc.cx(i + 1, 0)

    # Apply m_after
    if m_after == 1:
        qc.x(0)

    # Apply k_after
    for i in range(n):
        if (k_after >> i) & 1:
            qc.cx(i + 1, 0)

    # Apply m_new
    if m_new == 1:
        qc.x(0)

    # Apply k_new
    for i in range(n):
        if (k_new >> i) & 1:
            qc.cx(i + 1, 0)

    # Uncompute m_before
    if m_before == 1:
        qc.x(0)

    # Uncompute k_before
    for i in range(n):
        if (k_before >> i) & 1:
            qc.cx(i + 1, 0)

    return qc
